DO $test$
DECLARE u uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); unverified uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); k uuid:=gen_random_uuid(); ka uuid:=gen_random_uuid(); ia jsonb; ib jsonb; again jsonb; n bigint; before_entitlements bigint;
BEGIN
 SELECT count(*) INTO before_entitlements FROM mariz_core.product_entitlements;
 BEGIN
 INSERT INTO neon_auth."user"(id,name,email,"emailVerified") VALUES(u,'MARIZ fixture A','billing-a-'||u||'@example.invalid',true),(v,'MARIZ fixture B','billing-b-'||v||'@example.invalid',true),(unverified,'Unverified fixture','billing-u-'||unverified||'@example.invalid',false);
 INSERT INTO neon_auth.organization(id,name,slug,"createdAt") VALUES(a,'Sandbox A','billing-a-'||a,now()),(b,'Sandbox B','billing-b-'||b,now());
 INSERT INTO neon_auth.member(id,"organizationId","userId",role,"createdAt") VALUES(gen_random_uuid(),a,u,'owner',now()),(gen_random_uuid(),b,v,'admin',now()),(gen_random_uuid(),a,unverified,'owner',now());
 INSERT INTO mariz_core.company_profiles(organization_id,entity_type,legal_name,registration_no,registered_address,business_email,created_by) VALUES(a,'other','MARIZ SANDBOX TEST A','TEST-'||a,'Rollback-only address','test-a@example.invalid',u),(b,'other','MARIZ SANDBOX TEST B','TEST-'||b,'Rollback-only address','test-b@example.invalid',v);
 INSERT INTO mariz_billing.sandbox_organizations(organization_id,enabled) VALUES(a,true),(b,true);
 ia:=mariz_billing.reserve_billplz_invoice(u,a,k,'collection_fixture',100,'Test owner','test@example.invalid','Sandbox only');
 IF ia->>'payment_url' IS NOT NULL OR ia->>'status'<>'draft' THEN RAISE EXCEPTION 'URL exposed before registration'; END IF;
 again:=mariz_billing.reserve_billplz_invoice(u,a,k,'collection_fixture',100,'Test owner','test@example.invalid','Sandbox only');
 IF ia->>'id'<>again->>'id' THEN RAISE EXCEPTION 'Duplicate reservation'; END IF;
 BEGIN PERFORM mariz_billing.reserve_billplz_invoice(u,a,k,'collection_fixture',200,'Test owner','test@example.invalid','Sandbox only');RAISE EXCEPTION 'payload conflict accepted';EXCEPTION WHEN SQLSTATE '22023' THEN NULL;END;
 BEGIN PERFORM mariz_billing.reserve_billplz_invoice(v,a,ka,'collection_fixture',100,'Test owner','test@example.invalid','Sandbox only');RAISE EXCEPTION 'cross tenant reservation accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM mariz_billing.reserve_billplz_invoice(unverified,a,ka,'collection_fixture',100,'Test owner','test@example.invalid','Sandbox only');RAISE EXCEPTION 'unverified account accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM mariz_billing.billplz_invoice(v,(ia->>'id')::uuid);RAISE EXCEPTION 'cross tenant invoice read';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE mariz_billing.sandbox_organizations SET enabled=false WHERE organization_id=a;
 BEGIN PERFORM mariz_billing.claim_billplz_invoice(u,(ia->>'id')::uuid);RAISE EXCEPTION 'unapproved organization accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE mariz_billing.sandbox_organizations SET enabled=true WHERE organization_id=a;
 IF NOT mariz_billing.claim_billplz_invoice(u,(ia->>'id')::uuid) OR mariz_billing.claim_billplz_invoice(u,(ia->>'id')::uuid) THEN RAISE EXCEPTION 'issuance claim not exclusive';END IF;
 BEGIN PERFORM mariz_billing.register_billplz_invoice(u,(ia->>'id')::uuid,'fixture_a','wrong_collection',100,'https://www.billplz-sandbox.com/bills/fixture_a');RAISE EXCEPTION USING ERRCODE='ZX002',MESSAGE='bad collection accepted';EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL;END;
 ia:=mariz_billing.register_billplz_invoice(u,(ia->>'id')::uuid,'fixture_a','collection_fixture',100,'https://www.billplz-sandbox.com/bills/fixture_a');
 IF ia->>'provider_bill_id'<>'fixture_a' OR ia->>'issuance_state'<>'registered' THEN RAISE EXCEPTION 'registration failed';END IF;
 IF mariz_billing.record_billplz_callback_v2('unknown_fixture',100,true,'paid',repeat('a',64),'collection_fixture') THEN RAISE EXCEPTION 'unknown callback accepted';END IF;
 IF mariz_billing.record_billplz_callback_v2('fixture_a',100,true,'paid',repeat('a',64),'wrong_collection') THEN RAISE EXCEPTION 'wrong collection accepted';END IF;
 IF mariz_billing.record_billplz_callback_v2('fixture_a',101,true,'paid',repeat('a',64),'collection_fixture') THEN RAISE EXCEPTION 'wrong amount accepted';END IF;
 IF mariz_billing.record_billplz_callback_v2('fixture_a',100,false,'paid',repeat('a',64),'collection_fixture') THEN RAISE EXCEPTION 'contradictory state accepted';END IF;
 IF NOT mariz_billing.record_billplz_callback_v2('fixture_a',100,false,'due',repeat('b',64),'collection_fixture') THEN RAISE EXCEPTION 'unpaid callback failed';END IF;
 IF (mariz_billing.billplz_invoice(u,(ia->>'id')::uuid))->>'status'<>'due' THEN RAISE EXCEPTION 'unpaid event activated paid';END IF;
 IF NOT mariz_billing.record_billplz_callback_v2('fixture_a',100,true,'paid',repeat('c',64),'collection_fixture') THEN RAISE EXCEPTION 'paid callback failed';END IF;
 IF NOT mariz_billing.record_billplz_callback_v2('fixture_a',100,true,'paid',repeat('c',64),'collection_fixture') THEN RAISE EXCEPTION 'duplicate callback not acknowledged';END IF;
 IF NOT mariz_billing.record_billplz_callback_v2('fixture_a',100,false,'due',repeat('d',64),'collection_fixture') THEN RAISE EXCEPTION 'late callback failed';END IF;
 IF (mariz_billing.billplz_invoice(u,(ia->>'id')::uuid))->>'status'<>'paid' THEN RAISE EXCEPTION 'paid state regressed';END IF;
 SELECT count(*) INTO n FROM mariz_billing.provider_events WHERE payment_request_id=(ia->>'id')::uuid;
 IF n<>3 THEN RAISE EXCEPTION 'replay duplicated event';END IF;
 ib:=mariz_billing.reserve_billplz_invoice(v,b,gen_random_uuid(),'collection_fixture',200,'Test owner','test@example.invalid','Sandbox only');
 PERFORM mariz_billing.claim_billplz_invoice(v,(ib->>'id')::uuid);
 ib:=mariz_billing.register_billplz_invoice(v,(ib->>'id')::uuid,'fixture_b','collection_fixture',200,'https://www.billplz-sandbox.com/bills/fixture_b');
 IF mariz_billing.record_billplz_callback_v2('fixture_b',200,true,'paid',repeat('c',64),'collection_fixture') THEN RAISE EXCEPTION 'cross bill digest replay accepted';END IF;
 BEGIN PERFORM mariz_billing.record_billplz_reconciliation(u,(ib->>'id')::uuid,'fixture_b',200,true,'paid',repeat('e',64),'collection_fixture');RAISE EXCEPTION 'cross tenant reconciliation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF NOT mariz_billing.record_billplz_reconciliation(v,(ib->>'id')::uuid,'fixture_b',200,true,'paid',repeat('e',64),'collection_fixture') THEN RAISE EXCEPTION 'reconciliation failed';END IF;
 IF (mariz_billing.billplz_invoice(v,(ib->>'id')::uuid))->>'status'<>'paid' THEN RAISE EXCEPTION 'reconciliation did not record paid';END IF;
 IF (SELECT count(*) FROM mariz_billing.audit_events WHERE request_id=(ia->>'id')::uuid)<6 THEN RAISE EXCEPTION 'audit records missing';END IF;
 IF (SELECT count(*) FROM mariz_core.product_entitlements)<>before_entitlements THEN RAISE EXCEPTION 'entitlement changed';END IF;
 IF has_table_privilege('mariz_billing_runtime_limited','mariz_billing.payment_requests','SELECT,INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'direct billing grants';END IF;
 IF has_function_privilege('mariz_billing_runtime_limited','mariz_billing.record_billplz_callback(text,integer,boolean,text,text)','EXECUTE') THEN RAISE EXCEPTION 'legacy bypass grant retained';END IF;
 IF NOT has_function_privilege('mariz_billing_runtime_limited','mariz_billing.record_billplz_callback_v2(text,integer,boolean,text,text,text)','EXECUTE') THEN RAISE EXCEPTION 'callback grant missing';END IF;
 RAISE EXCEPTION USING ERRCODE='ZX001',MESSAGE='rollback synthetic fixture';
 EXCEPTION WHEN SQLSTATE 'ZX001' THEN NULL;
 END;
 IF EXISTS(SELECT 1 FROM neon_auth."user" WHERE id=u) OR EXISTS(SELECT 1 FROM mariz_billing.payment_requests WHERE organization_id IN(a,b)) THEN RAISE EXCEPTION 'fixture rollback failed';END IF;
END $test$;
